<script setup lang="ts">
import { canReviewSources, parseReviews, parseSource } from '~/utils/provenance'
definePageMeta({ access: { catalog: true } })
useHead({ title: 'Первоисточник · Школьные события' })
const route = useRoute(), api = useApi(), auth = useAuthStore()
const { data, error, pending, refresh } = useProvenanceResource(async signal => parseSource(await api.request('get', '/event-sources/{id}', { params: { id: String(route.params.id) }, signal, reportError: false })), () => route.params.id)
const historyOpen = ref(false)
watch(() => route.params.id, () => { historyOpen.value = false })
const history = useProvenanceResource(async signal => parseReviews(await api.request('get', '/event-sources/{id}/reviews', { params: { id: String(route.params.id) }, signal, reportError: false })), () => route.params.id, () => historyOpen.value && canReviewSources(auth.systemRole) && !!data.value)
</script>
<template><div class="provenance-page"><NuxtLink :to="data ? `/calendar/${encodeURIComponent(data.calendar_event_id)}` : '/calendar'">← К событию</NuxtLink><header><p class="provenance-eyebrow">Культурный каталог</p><h1>Первоисточник</h1></header><UiCard v-if="pending"><UiState kind="loading" title="Загружаем первоисточник" /></UiCard><UiCard v-else-if="error"><UiState kind="error" title="Источник недоступен" :description="error.message"><UiButton @click="refresh">Повторить</UiButton></UiState></UiCard><template v-else-if="data"><UiCard><SourceContent :source="data" /><NuxtLink v-if="canReviewSources(auth.systemRole)" :to="{ path: '/catalog', query: { source: data.id } }">Управление источником и экспертиза →</NuxtLink></UiCard><UiCard><div class="provenance-stack"><h2>Экспертная проверка</h2><p v-if="!canReviewSources(auth.systemRole)" class="muted">Полный журнал рецензий доступен кураторам и системным администраторам. Последнее решение показано в карточке источника.</p><template v-else><UiButton variant="secondary" :aria-expanded="historyOpen" @click="historyOpen = !historyOpen">{{ historyOpen ? 'Скрыть журнал' : 'История экспертных решений' }}</UiButton><template v-if="historyOpen"><UiState v-if="history.pending.value" kind="loading" title="Загружаем рецензии" /><UiState v-else-if="history.error.value" kind="error" title="Журнал недоступен" :description="history.error.value.message"><UiButton @click="history.refresh">Повторить</UiButton></UiState><ReviewHistory v-else-if="history.data.value" :reviews="history.data.value" /></template></template><UiButton variant="secondary" @click="refresh">Обновить сведения</UiButton></div></UiCard></template></div></template>
